SELECT p.gender, a.admission_type, COUNT(a.hadm_id) AS n, AVG(a.los) AS avg_los, STDDEV(a.los) AS stddev_los, SUM(CASE WHEN a.los < 10 THEN 1 ELSE 0 END) AS los_lt_10_days FROM patients p JOIN admissions a ON p.subject_id = a.subject_id WHERE p.gender = 'F' AND EXTRACT(YEAR FROM age(CURRENT_DATE, p.dob)) BETWEEN 87 AND 97 AND a.discharge_location IN ('home', 'facility') GROUP BY p.gender, a.admission_type ORDER BY p.gender, a.admission_type NULLS LAST;